INSERT OR IGNORE INTO quiz_questions(category,topic,question,options_json,correct_index,explanation,source_url,active) VALUES ('umum','Air Bersih & Kesehatan','Jika air berbau bahan kimia menyengat, apa yang sebaiknya dilakukan?','["Jangan diminum sebelum sumber dan keamanannya diperiksa","Rebus lalu pasti semua bahan kimia hilang","Tambahkan pewarna agar baunya tertutup","Minum sedikit untuk menguji efek"]',0,'Perebusan tidak menjamin hilangnya kontaminan kimia sehingga sumber perlu diperiksa.','https://www.who.int/news-room/fact-sheets/detail/drinking-water',1);
