INSERT OR IGNORE INTO quiz_questions(category,topic,question,options_json,correct_index,explanation,source_url,active) VALUES ('umum','Air Bersih & Kesehatan','Sebuah desa kekurangan air aman saat kemarau. Prioritas pengelolaan apa?','["Utamakan kebutuhan air minum dan sanitasi dasar","Gunakan air aman hanya untuk mencuci kendaraan","Biarkan kebocoran pipa","Tiadakan informasi pembagian air"]',0,'Prioritas air untuk minum dan sanitasi membantu melindungi kesehatan warga.','https://www.who.int/news-room/fact-sheets/detail/drinking-water',1);
